\begin{equation}\label{domain X}
\mathcal{X} := \left\{ \mathbf{x} \in \mathbb{R}^n: \ g_j(\mathbf{x}) \geq 0 \ \forall j \in [m],\;
h_i(x) = 0\ \forall\; i\in [p] \right\},
\end{equation}
where each $g_j$ and $h_i$ is a polynomial in $\mathbb{R}[\mathbf{x}]$.

