\label{thm: Schmüdgen}
    Let $\mathcal{X}$ be the semi-algebraic set in \eqref{domain X}.
    We assume that $\mathcal{X}$ is compact. If $f$ is a positive polynomial on $\mathcal{X}$, then $f \in \mathcal{T}(\mathcal{X})$.

\begin{eqnarray} 
    \mathcal{R}(\mathcal{X})_{2r} &:=& \Biggl\{q(\mathbf{x}) = \sum_{j=1}^N\sigma_{J_j}(\mathbf{x})g_{J_j}(\mathbf{x}) + \sum_{i=1}^p\tau_ih_i^2(\mathbf{x}) \in 
    \mathcal{T}(\mathcal{X}): \; \tau_i \in \mathbb{R}_{\geq 0} \ \forall i \in [p],\;
    \nonumber \\    
   &&\quad \exists N \in \mathbb{N},\; J_j\subset [m],\; \sigma_{J_j} \in \Sigma[\mathbf{x}]_{2(r-\lceil g_{J_j} \rceil) } \ \forall j \in [N]
     \Biggr\}.
     \label{eq-RX}
\end{eqnarray}

We define the Riesz linear functional $\ell_{\mathit{y}}: \mathbb{R}[\mathbf{x}] \to \mathbb{R}$ as follows: 
\begin{displaymath}
    f(\mathbf{x})= \sum_{\alpha \in \mathbb{N}^n}f_{\alpha}x^{\alpha} \quad \mapsto \quad \ell_{\mathit{y}}(f) = \sum_{\alpha \in \mathbb{N}^n}f_{\alpha}y_{\alpha}.

We utilize $\ell_{\mathit{y}}$ to set up the moment matrix and localizing matrix as follows: given an infinite sequence $\mathit{y}$ as above, the moment matrix $\mathbf{M}(\mathit{y})$ with rows and columns indexed by $\mathbf{v}(\mathbf{x})$ is defined by
\begin{displaymath}
    \mathbf{M}(\mathit{y})(\alpha, \beta) = \ell_{\mathit{y}}(\mathbf{x}^{\alpha+\beta})=y_{\alpha +\beta}, \quad \forall \alpha, \beta \in \mathbb{N}^n.

\end{displaymath}
For a given $r \in \mathbb{N}$, the $r$-truncated moment matrix, denoted by $\mathbf{M}_r(\mathit{y})$, is the submatrix of $\mathbf{M}(\mathit{y})$ obtained by extracting the rows and columns of $\mathbf{M}(\mathit{y})$
indexed by $\mathbf{v}_r(\mathbf{x})$.

\begin{align}\label{hierarchy: moment Schmudgen}
   & \mathrm{mlb}(f,\mathcal{T}(\mathcal{X}))_r = \inf \Big\{ \ell_{\mathit{y}}(f) = \sum_{\alpha \in \mathbb{N}^n_{2r}}f_{\alpha}y_{\alpha} \,:\, \mathit{y} \in \mathcal{M}(\mathcal{T}(\mathcal{X})_{2r})\Big\}
    \\
    \text{where \quad} & \mathcal{M}(\mathcal{T}(\mathcal{X})_{2r}) := \Big\{ 
    \mathit{y}\in 
    \mathbb{R}^{s(n,2r)}\,:\,\ y_0 =1,\ \mathbf{M}_r(\mathit{y}) \succeq 0,\ \mathbf{M}_{r - \lceil h_i \rceil}(h_i \mathit{y}) = 0 \; \forall i \in [p] \nonumber\\ 
    &\hspace{30mm}  \mathbf{M}_{r-\lceil g_J \rceil}(g_J\mathit{y}) \succeq 0\;\;
     \forall\; J \subset [m] \;\mbox{such that} \; \lceil g_J \rceil\leq r \Big\}
    \nonumber.
\end{align}

\begin{equation}\label{hierarchy: SOS Schmudegen}
    \mathrm{lb}(f,\mathcal{T}(\mathcal{X}))_r = \sup\{c \in \mathbb{R}:\ f(\mathbf{x}) -c \in \mathcal{T}(\mathcal{X})_{2r}\}.
\end{equation}

\begin{align}\label{hierarchy: moment Putinar}
    & \mathrm{mlb}(f,\mathcal{Q}(\mathcal{X}))_r = \inf\Big\{ \ell_{\mathit{y}}(f) = \sum_{\alpha \in \mathbb{N}^n_{2r}}f_{\alpha}y_{\alpha}\,:\, \mathit{y} \in {\cal M}(\mathcal{Q}(\mathcal{X})_{2r}) \Big\}
    \\
    \text{where \quad}& {\cal M}(\mathcal{Q}(\mathcal{X})_{2r}) :=\Big\{ \mathit{y} \in \mathbb{R}^{s(n,2r)}\,:\, y_0 =1,\ \mathbf{M}_r(\mathit{y}) \succeq 0, \;
      \mathbf{M}_{r-\lceil g_i \rceil}(g_i\mathit{y}) \succeq 0 \ \forall\; i \in [m]\Big\}.
    \nonumber
\end{align}

These SDP relaxations form the Putinar-type moment hierarchy, whose 
dual problems form the Putinar-type SOS hierarchy defined by
\begin{equation}\label{hierarchy: SOS Putinar}
    \mathrm{lb}(f,\mathcal{Q}(\mathcal{X}))_r = \sup\{c \in \mathbb{R}:\ f(\mathbf{x}) -c \in \mathcal{Q}(\mathcal{X})_{2r}\}.
\end{equation}

\begin{equation}\label{hierarchy: SOS Putinar}
    \mathrm{lb}(f,\mathcal{Q}(\mathcal{X}))_r = \sup\{c \in \mathbb{R}:\ f(\mathbf{x}) -c \in \mathcal{Q}(\mathcal{X})_{2r}\}.
\end{equation}

\begin{align}\label{hierarchy: reduced moment}
   & \mathrm{mlb}(f,\mathcal{R}(\mathcal{X}))_r = \inf \Big\{ \ell_{\mathit{y}}(f) = \sum_{\alpha \in \mathbb{N}^n_{2r}}f_{\alpha}y_{\alpha} \,:\, \mathit{y} \in \mathcal{M}(\mathcal{R}(\mathcal{X})_{2r})\Big\}
    \\
    \text{where \quad} & \mathcal{M}(\mathcal{R}(\mathcal{X})_{2r}) := \Big\{ 
    \mathit{y}\in 
    \mathbb{R}^{s(n,2r)}\,:\,\ y_0 =1,\ \mathbf{M}_r(\mathit{y}) \succeq 0, \nonumber\\ 
    &\hspace{30mm}  \ell_{\mathit{y}}(h_i^2(\mathbf{x}))=0\ \forall i \in [p],\; \mathbf{M}_{r-\lceil g_J \rceil}(g_J\mathit{y}) \succeq 0\;\;
     \forall\; J \subset [m] \;\mbox{s.t} \; \lceil g_J \rceil\leq r \Big\}
    \nonumber,
\end{align}

\begin{equation}\label{hierarchy: reduced SOS}
    \mathrm{lb}(f,\mathcal{R}(\mathcal{X}))_r = \sup\{c \in \mathbb{R}:\ f(\mathbf{x}) -c \in \mathcal{R}(\mathcal{X})_{2r}\}.
\end{equation}

It is straightforward from the definitions that the following inequalities hold:
\begin{displaymath}
    \mathrm{lb}(f,\mathcal{R}(\mathcal{X}))_r \leq  \mathrm{mlb}(f,\mathcal{R}(\mathcal{X}))_r \leq  \mathrm{mlb}(f,\mathcal{T}(\mathcal{X}))_r, \quad \mathrm{lb}(f,\mathcal{R}(\mathcal{X}))_r \leq \mathrm{lb}(f,\mathcal{T}(\mathcal{X}))_r.

\label{remark: Archimedian condition}
    In this paper, we aim to determine the asymptotic convergence rate of the moment-SOS hierarchy for a compact semi-algebraic set $\mathcal{X}$. Since $\mathcal{X}$ is bounded, there exists a constant $R$ such that the ball $\mathbb{B}_R$ (with radius $R$ and center at the origin) contains $\mathcal{X}$. Without loss of generality, we can assume that $R- \|\mathbf{x}\|^2$ is positive over $\mathcal{X}$. The Schm\"udgen Positivstellensatz theorem implies that there exists a positive integer $t$ such that $R- \|\mathbf{x}\|^2 \in \mathcal{T}(\mathcal{X})_{2t}$. Therefore, if we set $\mathcal{T}(\mathcal{X}')_{2r}$ to be the preordering of order $2r$ of $\mathcal{X}$ 
    with the additional constraint $R- \|\mathbf{x}\|^2 \geq 0$, then we have 
\begin{displaymath}
     \mathcal{T}(\mathcal{X}')_{2r}\subset \mathcal{T}(\mathcal{X})_{2r+2t} \quad \forall\; r \in \mathbb{N}.
\end{displaymath}
This means that the asymptotic convergence rates of $\mathrm{mlb}(f,\mathcal{T}(\mathcal{X}))_r$ and $\mathrm{lb}(f,\mathcal{T}(\mathcal{X}))_r$ are equal to that of $\mathrm{mlb}(f,\mathcal{T}(\mathcal{X}'))_r$ and $\mathrm{lb}(f,\mathcal{T}(\mathcal{X}'))_r$, respectively. Therefore, without loss of generality,
throughout this paper, most results will be stated under the assumption that the ball constraint $R^2 - \|\mathbf{x}\|^2 \geq 0$ for some suitable $R$ is added to the description~\eqref{domain X} of $\mathcal{X}$.

