\begin{eqnarray*}
        \qquad f_{\min} - \mathrm{mlb}(f,\mathcal{T}(\mathcal{X}))_r &\leq& \|f\|_1\,\mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r}),\\
        \qquad f_{\min} - \mathrm{mlb}(f,\mathcal{R}(\mathcal{X}))_r &\leq&\|f\|_1\,\mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}),\\
        \qquad f_{\min} - \mathrm{mlb}(f,\mathcal{Q}(\mathcal{X}))_r &\leq&\|f\|_1\,\mathbf{d}_k(\mathcal{Q}(\mathcal{X})_{2r}).
    \end{eqnarray*}

We only prove the result for the preordering $\mathcal{T}(\mathcal{X})_{2r}$ since it is similar for the quadratic module $\mathcal{Q}(\mathcal{X})_{2r}$ and $\mathcal{R}(\mathcal{X})_{2r}$. Notice that the problem \eqref{POP} admits an equivalent formulation defined by $k$-truncated moment sequences as follows:
    \begin{displaymath}
        f_{\min} = \inf \left\{\sum_{\alpha \in \mathbb{N}^n_k}f_{\alpha}\mathit{y}_{\alpha}=\langle \mathbf{f},\mathit{y} \rangle:\ \mathit{y} \in \mathcal{M}_k(\mathcal{X}) \right\}.
    \end{displaymath}
    Since $\mathcal{X}$ is compact, so is $\mathcal{M}_k(\mathcal{X})$. For any $\mathit{y} \in \mathcal{M}_k(\mathcal{T}(\mathcal{X})_{2r})$, there exists its projection $\overline{\mathit{y}} \in \mathcal{M}_k(\mathcal{X})$ such that $\|\mathit{y} - \overline{\mathit{y}}\| = \mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r})$. Hence the Cauchy–Schwarz inequality implies that 
    \begin{displaymath}
       \left| \langle \mathbf{f},\mathit{y} \rangle- \langle \mathbf{f},\overline{\mathit{y}} \rangle\right| \leq \|f\|_1\mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r})\ \Rightarrow \  f_{\min} - \mathrm{mlb}(f,\mathcal{T}(\mathcal{X}))_r \leq \|f\|_1\,\mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r}).
    \end{displaymath}
    This completes the proof.

