\label{thm: CD kernel on simple sets} 
Let $\mathcal{X}$ be either the unit ball $B_n$ or the standard simplex $\Delta_n$. For any $k \in \mathbb{N}$ such that $r \geq 2(n+1)k$, there exist $1/2 \leq \lambda_i \leq 1 \ \forall i=\{0,\dots,2r\}$ 
such that $C_{2r}[\mathcal{X},\mu,\lambda](\cdot,\mathbf{y}) \in \mathcal{T}(\mathcal{X})_{2r}$ for any fixed $\mathbf{y} \in \mathcal{X}$, and the associated operator $\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]$ is an invertible linear operator on $\mathbb{R}[\mathbf{x}]_k$ satisfying the following properties:
\begin{align*}
   &\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda](1) =1,\\
   &\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]f \in \mathcal{T}(\mathcal{X})_{2r} \quad \forall\; f \in \mathbb{R}[\mathbf{x}]_k \;\mbox{such that}\; f(\mathbf{x}) \geq 0 \ \forall \mathbf{x} \in \mathcal{X},\\
   &\|\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]^{-1}f-f\|_{\mathcal{X}} \leq \gamma(\mathcal{X},k)\dfrac{c(n,k)}{r^2}\|f\|_{\mathcal{X}} \quad \forall\; f\in \mathbb{R}[\mathbf{x}]_k,
\end{align*}
where $c(n,k) = 2(n+1)^2k^2$, $\|f\|_{\mathcal{X}}=\max_{\mathbf{x} \in \mathcal{X}}|f(\mathbf{x})|$,
and $\gamma(\mathcal{X},k)$ is the harmonic constant depending on $\mathcal{X}$ (which depends polynomially on $n$ for fixed $k$, polynomially on $k$ for fixed $n$).

\begin{align*}
    &\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda](1) =1,\\
    &\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]f \in \mathcal{T}(\mathcal{X})_{2r} \quad \forall\; f \in \mathbb{R}[\mathbf{x}]_k \;\mbox{such that}\; f(\mathbf{x}) \geq 0 \ \forall \mathbf{x} \in \mathcal{X},\\
    &\|\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]^{-1}f-f\|_{\mathcal{X}} \leq \gamma(\mathcal{X},k)\dfrac{c(n,k)}{r^2}\|f\|_{\mathcal{X}} \quad \forall\; f\in \mathbb{R}[\mathbf{x}]_k,
 \end{align*}

