 \begin{displaymath}
     \mathbf{K} f(\mathbf{x}) =\sum_{j=1}^N K(\mathbf{x},\mathbf{x}_j)w_j f(\mathbf{x}_j) \in \mathcal{T}(\mathcal{X})_{2mr}. 
 \end{displaymath}

