    &\leq& \left( \sum_{j_1\dots+j_m \leq k}\left|1-\dfrac{1}{\prod_{i=1}^m\lambda^{(i)}_{j_i}} \right| \right) \Lambda(\mathcal{X},k) \|f\|_{\mathcal{X}}.
\end{eqnarray}
 Taking maximum on both sides of \eqref{equation 1} over $\mathbf{x} \in \mathcal{X}$, we obtain that 
\begin{displaymath}
    \|\mathbf{K}^{-1}f -f\|_{\mathcal{X}} \leq \Lambda(\mathcal{X},k) \|f\|_{\mathcal{X}} \sum_{j_1+\dots+j_m \leq k}\left|1-\dfrac{1}{\prod_{i=1}^m\lambda^{(i)}_{j_i}} \right|.
\end{displaymath}
Based on Lemma~\ref{lemma: recall results}, we know that for all $i \in [m]$ and $0 \leq j \leq 2r $, we have $\lambda^{(i)}_j \in [1/2,1]$. Then 
\begin{eqnarray}
    && \hspace{-7mm}
    \sum_{j_1+\dots+j_m \leq k}\left|1-\dfrac{1}{\prod_{i=1}^m\lambda^{(i)}_{j_i}} \right|= \sum_{j_1+\dots+j_m \leq k}\frac{1- \prod_{i=1}^m\lambda^{(i)}_{j_i}}{\prod_{i=1}^m\lambda^{(i)}_{j_i}}\leq \sum_{j_1+\dots+j_m \leq k}\frac{\sum_{i=1}^m (1- \lambda^{(i)}_{j_i})}{\prod_{i=1}^m\lambda^{(i)}_{j_i}}
