\end{equation*}
In the proof of Theorem~\ref{thm: CD on product}, we have pointed out that $\sigma(\mathbf{x}):= C_{2r}[\mathcal{X},\mu,\lambda](\mathbf{x},\mathbf{x}^*)\in \mathcal{T}(\mathcal{X})_{2mr}$. Whence, we have 
\begin{equation*}
    f_{\min} \leq \mathrm{ub}(f,\mathcal{T}(\mathcal{X}))_{mr} \leq \int_{\mathcal{X}}f(\mathbf{x})\sigma(\mathbf{x})d\mu(\mathbf{x})=\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]f(\mathbf{x}^*).
\end{equation*}
Note that $f(\mathbf{x})$ admits the following decomposition
\begin{displaymath}
         f(\mathbf{x}) = \sum_{j_1+\dots+j_m  \leq k}f_{j_1,\dots,j_m}(\mathbf{x}),\quad f_{j_1,\dots,j_m} \in S_{j_1,\dots,j_m}\ \forall j_1+\dots+j_m \leq k.     
\end{displaymath}
Thus, the image of $f$ under $\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]$ is 
\begin{equation*}
    \mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]f(\mathbf{x}) = \sum_{j_1+\dots+j_m  \leq k} \Big(\prod_{i=1}^m\lambda^{(i)}_{j_i}\Big) 
    f_{j_1,\dots,j_m}(\mathbf{x}).
\end{equation*}
Therefore we can bound 
