        \leq\;&\binom{k+m-1}{m-1}\left(\sum_{i=1}^m\sum_{j=1}^k\Big|1-\frac{1}{\lambda^{(i)}_{j}} \Big|\right)
        \Lambda(\mathcal{X},k)\|f\|_{\mathcal{X}}\quad \text{(since $\lambda^{(i)}_j \in [{1}/{2},1]$)}\\
        \leq\;& \binom{k+m-1}{m-1}\left(\sum_{i=1}^m c(n_i,k)\right)\frac{\Lambda(\mathcal{X},k)\|f\|_{\mathcal{X}}}{r^2},
\end{align*}
where the last inequality follows from Lemma~\ref{lemma: recall results}, which leads to our desired bound.

