We prove the theorem by evaluating the distance between an arbitrary pseudo-moment sequence $\mathit{y} \in \mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r})$ and $\mathcal{M}_k(\mathcal{X})$. First, we conduct two consecutive projections as follows: since $\mathcal{M}_k(\mathcal{X}) \subset \mathcal{M}_k(\mathcal{Y})$,
we first project $\mathit{y}$ onto $\mathcal{M}_k(\mathcal{Y})$ and denote its projection by $\overline{\mathit{y}}$. By Tchakaloff's theorem, $\overline{\mathit{y}}$ can be written as a convex combination of some $\mathbf{v}_k(\overline{\mathbf{x}}_j)'$s with points $\{\overline{\mathbf{x}}_j : j\in[N]\} \subset \mathcal{Y}$. We continue projecting $\overline{\mathbf{x}}_j$ onto $\mathcal{X}$ to define a new moment sequence $\widetilde{\mathit{y}} \in \mathcal{M}_k(\mathcal{X})$. These projections are demonstrated in Figure~\ref{Fig: projection with real algebraic variety} and elaborated in the later part of the proof. Then we can upper bound the distance of $\mathit{y}$ to $\mathcal{M}_k(\mathcal{X})$ by 
the triangle inequality: 
\begin{equation}\label{eq: inequality for distance with variety}
    \mathbf{d}(\mathit{y},\mathcal{M}_k(\mathcal{X})) \;\leq\; \|\mathit{y} - \widetilde{\mathit{y}}\| \;\leq\; \|\mathit{y}-\overline{\mathit{y}}\| + \|\overline{\mathit{y}}-\widetilde{\mathit{y}}\|.
\end{equation}
The idea of upper-bounding $\mathbf{d}(\mathit{y},\mathcal{M}_k(\mathcal{X}))$ by $\|\mathit{y}-\overline{\mathit{y}}\|$ and $\|\overline{\mathit{y}}-\widetilde{\mathit{y}}\|$ is based on the fact that we already have Theorem~\ref{thm: error on product of simple sets} and the Łojasiewicz inequality~\eqref{Lojaciewicz inequality} as tools to evaluate these terms, which is elaborated next. 

\textbf{Evaluating $\|\mathit{y}-\overline{\mathit{y}}\|$:}  according to Theorem~\ref{thm: error on product of simple sets} under the 
condition $r \geq 2s(\max\{n_1,\dots,n_s\}+1)k+s$, we have
    \begin{equation}\label{eq: inequality for distance with variety 1}
        \|\mathit{y} -\overline{\mathit{y}}\| \;\leq\; 
        \dfrac{2\gamma(R,n,k)\,\Gamma(\mathcal{Y},k)}{(r-s)^2}\;=: \varepsilon
    \end{equation}

    \textbf{Evaluating $\|\overline{\mathit{y}}-\widetilde{\mathit{y}}\|$:} according to Tchakaloff's theorem, there exists at most $N = s(n,k)$ points $\{\overline{\mathbf{x}}_j:j\in[N]\}$ in $\mathcal{Y}$ and positive real numbers $\{w_j : j\in[N]\}$ such that $\sum_{j=1}^N w_j =1$ and
    \begin{displaymath}
        \overline{\mathit{y}}= \sum_{j=1}^N w_j\mathbf{v}_k(\overline{\mathbf{x}}_j).
    \end{displaymath}
    Therefore, we can rewrite the equalities of the Riesz functional associated with $\mathit{y}$ and $\overline{\mathit{y}}$ as follows:
    \begin{equation*}
        \ell_{\mathit{y}}(h_i^2) = \langle \mathbf{h}_i^2, \mathit{y} \rangle= 0, 
        \quad \mbox{and} \quad  \ell_{\overline{\mathit{y}}}(h_i^2) =\langle \mathbf{h}_i^2, \overline{\mathit{y}} \rangle= \sum_{j=1}^N w_j \langle \mathbf{h}_i^2,\mathbf{v}_k(\overline{\mathbf{x}}_j)\rangle =
        \sum_{j=1}^N w_j h_i^2(\overline{\mathbf{x}}_j),
    \end{equation*}
    where $\mathbf{h}_i^2$ denotes the vector of coefficients of $h_i^2(\mathbf{x})$. Since $\|\mathit{y} -\overline{\mathit{y}}\| \leq \varepsilon$, by the Cauchy–Schwarz 
    inequality, we have the following inequality for any $i \in [p]$:
    \begin{eqnarray*}
        &\varepsilon \|h_i^2\|_1 \geq \left| \langle \mathbf{h}^2_i, \mathit{y} - \overline{\mathit{y}} \rangle \right| = \Big| \ell_{\mathit{y}}(h_i^2) - \sum_{j=1}^N w_j {h}_i^2(\overline{\mathbf{x}}_j)  \Big| 
        = \sum_{j=1}^N w_j h_i(\overline{\mathbf{x}}_j)^2.
    \end{eqnarray*}
     Thus, applying the Cauchy–Schwarz inequality again, we obtain that
    \begin{eqnarray*}
     \varepsilon \sum_{i=1}^p \|h_i^2\|_{1} 
     &\geq& \sum_{j=1}^N w_j \sum_{i=1}^p h_i(\overline{\mathbf{x}}_j)^2 \geq \sum_{j=1}^N w_j 
        \max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\}^2
        \\
        &=& \left(\sum_{j=1}^N w_j\right)\left(\sum_{j=1}^N w_j \max\left\{ h_i(\overline{\mathbf{x}}_j):\ i \in [p]\right\}^2\right)
        \\
        & \geq& \left(\sum_{j=1}^N w_j \max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\} \right)^2
        \\
        \Rightarrow \ \varepsilon^{1/2} \Big(\sum_{i=1}^p \|h_i^2\|_{1}\Big)^{1/2}
        &\geq& \sum_{j=1}^N w_j \max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\} .
    \end{eqnarray*}

        Let ${\mathbf{x}}_j\in\mathcal{X}$ be the projection of $\overline{\mathbf{x}}_j\in\mathcal{Y}$ onto $\mathcal{X}$ for all $j \in [N]$. We define 
    \begin{equation*}
        \widetilde{\mathit{y}} \;=\; \sum_{j=1}^N w_j\mathbf{v}_k({\mathbf{x}}_j) \;\in \mathcal{M}_k(\mathcal{X}).
    \end{equation*}
    In addition, based on the Łojasiewicz inequality~\eqref{Lojaciewicz inequality}, we have
    \begin{displaymath}
        \|\mathbf{x}_j -\overline{\mathbf{x}}_j\| = \mathbf{d}_{\mathcal{X}}(\overline{\mathbf{x}}_j) \leq c \max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\}^{\textit{\L}}\;\;\forall\; j\in[N].
    \end{displaymath}
    We then use the common Lipschitz number $L(R,k)$ to get the inequality below:
    \begin{displaymath}
        \|\mathbf{v}_k(\mathbf{x}_j) - \mathbf{v}_k(\overline{\mathbf{x}}_j)\| \leq L(R,k) \|\mathbf{x}_j -\overline{\mathbf{x}}_j\|  \leq cL(R,k) \max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\}^{\textit{\L}}\;\;\forall\; j\in[N].
    \end{displaymath}
    Hence, we obtain that 
    \begin{align*}
        &\|\overline{\mathit{y}}-\widetilde{\mathit{y}}\|\;=\;\left\|\sum_{j=1}^N 
        w_j\mathbf{v}_k(\overline{\mathbf{x}}_j) -\sum_{j=1}^N w_j\mathbf{v}_k(\mathbf{x}_j)\right\|\\ 
        \leq\;& \sum_{j=1}^N w_j\|\mathbf{v}_k(\overline{\mathbf{x}}_j) - \mathbf{v}_k(\mathbf{x}_j)\| 
        \;\leq \; cL(R,k)\sum_{j=1}^N w_j\max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\}^{\textit{\L}}.
    \end{align*} 
    Since $\textit{\L} \leq 1$, applying the Jensen's inequality gives us the following inequality:
        \begin{displaymath}
            \sum_{j=1}^N w_j\max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\}^{\textit{\L}} \leq \left(\sum_{j=1}^N w_j\max\left\{ |h_i(\overline{\mathbf{x}}_j)|:\ i \in [p]\right\}\right)^{\textit{\L}}\leq  \varepsilon^{\textit{\L}/2} \left(\sum_{i=1}^p \|h_i^2\|_1 \right) ^{\textit{\L}/2}.
        \end{displaymath}
        Combining the above with the inequality \eqref{eq: inequality for distance with variety 1}, we obtain that 
        \begin{align*}
