            \;\leq \; \varepsilon + cL(R,k)\varepsilon^{\textit{\L}/2} \left(\sum_{i=1}^p \|h_i^2\|_{1} \right) ^{\textit{\L}/2}\\ 
            \leq\;&  \dfrac{2\gamma(R,n,k)\Gamma(\mathcal{Y},k)}{r^2}+ cL(R,k)\left(\dfrac{2\gamma(R,n,k)\Gamma(\mathcal{Y},k)}{(r-s)^2}\right)^{\textit{\L}/2}\left(\sum_{i=1}^p\|h_i^2\|_{1}\right)^{\textit{\L}/2}.
        \end{align*}
        This completes the proof.

