\label{lem: projection into lows dimension}
    For a positive integer $k=2l$, we define the projection $\psi_k:\; \mathbb{R}^{s(n+m,k)} \to \mathbb{R}^{s(n,k)}$ as follows:
    \begin{displaymath}
        \mathit{y} \in \mathbb{R}^{s(n+m,k)} \mapsto  \psi_k(y) \;\; 
        \mbox{such that}\;\;

        (\psi_k(y))_{\alpha} = y_{(\alpha,0_m)}\;
        \forall\; 
        \alpha \in \mathbb{N}^n_k.
    \end{displaymath}
    Then for any $2r\geq k$, the followings hold true.
    \begin{enumerate}
        \item If $\mathit{y} \in \mathcal{M}_k(\mathcal{T}(\mathbb{B}_R \times \Delta^m_K)_{2r})$, then $\psi_k(\mathit{y}) \in \mathcal{M}_k(\mathcal{T}(\mathbb{B}_R)_{2r})$.
        \item If $\mathit{y} \in \mathcal{M}_k(\mathcal{T}(\varphi(\mathcal{X}))_{2r})$, then $\psi_k(\mathit{y}) \in \mathcal{M}_k(\mathcal{T}(\mathcal{X})_{2r})$.
        \item If $\mathit{y} \in \mathcal{M}_k(\mathbb{B}_R \times \Delta^m_K)$, then $\psi_k(\mathit{y}) \in \mathcal{M}_k(\mathbb{B}_R)$.
        \item If If $\mathit{y} \in \mathcal{M}_k(\varphi(\mathcal{X}))$, then $\psi_k(\mathit{y}) \in \mathcal{M}_k(\mathcal{X})$.
    \end{enumerate}

\label{thm: error on general}
     Let $\mathcal{X} \in \mathbb{R}^n$ be a compact basic semi-algebraic set defined as in \eqref{eq-CX}. For any positive integers $k=2l$ and $r$ such that $t = \lfloor r/(2d) \rfloor$, $l \geq 2d$, and $t \geq 4(\max\{n,m\}+1)k+2$ the Hausdorff distance $\mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r})$ admits the following bound:
     \begin{multline*}
          \mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) \leq \Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)\dfrac{(2d)^2}{(r-4d)^2}\\+\frac{cL(R,k)(2d)^{\textit{\L}}}{(r-4d)^{\textit{\L}}}
            [\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)]^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}.
     \end{multline*}
     Here, the parameter $L(R,k)$ is the Lipschitz number of $\mathbf{v}_k(\mathbf{x})$ on the simple set $\mathbb{B}_R$. In short, the error for the set of truncated pseudo-moment sequences $\mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r})$
     is $\mathrm{O}(1/r^{\textit{\L}})$.

\begin{multline*}
          \mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) \leq \Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)\dfrac{(2d)^2}{(r-4d)^2}\\+\frac{cL(R,k)(2d)^{\textit{\L}}}{(r-4d)^{\textit{\L}}}
            [\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)]^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}.
     \end{multline*}

     Let $\mathit{y} \in \mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r})$ be an arbitrary truncated pseudo-moment sequence. We proceed to bound the distance from $\mathit{y}$ to $\mathcal{M}_k(\mathcal{X})$ by finding an appropriate point $\widetilde{\mathit{y}} \in \mathcal{M}_k(\mathcal{X})$ and a point $\overline{\mathit{y}} \in \mathcal{M}_k(\mathbb{B}_R)$ such that
     \begin{equation}\label{eq: inequality of distance with compactness}
         \mathbf{d}(\mathit{y},\mathcal{M}_k(\mathcal{X})) \leq \|\mathit{y}- \widetilde{\mathit{y}}\| \leq \|\mathit{y}- \overline{\mathit{y}}\| + \|\overline{\mathit{y}}- \widetilde{\mathit{y}}\|.
     \end{equation}
     The idea of finding $\overline{\mathit{y}}$ and $\widetilde{\mathit{y}}$ is through lifting $\mathcal{M}_k(\mathcal{X})$ to $\mathcal{M}(\mathcal{T}(\varphi(\mathcal{X}))_{2r})$, where $ \varphi(\mathcal{X})$ is the intersection of a real variety and the product $\mathbb{B}_R \times \Delta_K^m$ of simple sets. 
     We first find the corresponding points 
     $\overline{y}'$ and $\widetilde{y}'$ in the lifted spaces and then 
     obtain the desired points $\overline{y}$ and $\widetilde{y}$ by the 
     projection $\psi_k$ defined as in Lemma~\ref{lem: projection into lows dimension}.
     We can conduct the proof as in Theorem~\ref{thm: error on product of simple sets}. The detail is elaborated below.
     \begin{enumerate}
         \item Since $\mathit{y} \in \mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r})$, there exists $\widehat{\mathit{y}} \in \mathcal{M}(\mathcal{R}(\mathcal{X})_{2r})$ such that $\mathit{y} = \pi_k(\widehat{\mathit{y}})$. Lemma~\ref{lemma: lift of moment sequence} implies that 
         $\widehat{\mathit{y}}^{\varphi} \in \mathcal{M}(\mathcal{T}(\varphi(\mathcal{X}))_{2t})$. Let $\overline{\mathit{y}}^\prime \in \mathcal{M}_{2t}(\mathbb{B}_R \times \Delta_K^m)$ be the projection of $\widehat{\mathit{y}}^{\varphi}$ onto $\mathcal{M}_{2t}(\mathbb{B}_R \times \Delta_K^m)$. We set
         \begin{equation*}
             \overline{\mathit{y}}= \psi_k(\pi_k(\overline{\mathit{y}}^\prime)) \in \mathcal{M}_k(\mathbb{B}_R) \quad \text{(by Lemma~\ref{lem: projection into lows dimension})}.
         \end{equation*}
         \item By Tchakaloff's theorem, there exist at most $N = s(n+m,2t)$ points $\{\overline{\mathbf{z}}_1,\dots,\overline{\mathbf{z}}_N\} \subset \mathbb{B}_R \times \Delta_K^m$ and positive weights $\{w_s : s\in [N]\}$ satisfying that $\sum_{s=1}^Nw_s =1$ and 
         \begin{displaymath}
             \overline{\mathit{y}}^\prime = \sum_{s=1}^N w_s
             \mathbf{v}_{2t}(\overline{\mathbf{z}}_s).
         \end{displaymath}
         For any $s \in [N]$, $\overline{\mathbf{z}}_s = (\overline{\mathbf{x}}_s, \overline{u}_{s1},\dots,\overline{u}_{sm})$, we set ${\mathbf{x}}_s$ to be the projection of $\overline{\mathbf{x}}_s$ onto $\mathcal{X}$. 
         Then we define 
         \begin{eqnarray*}
            \widetilde{\mathit{y}}^\prime &=&\sum_{s=1}^Nw_s \mathbf{v}_{2t}\big( ({\mathbf{x}}_s,g_1({\mathbf{x}}_s),\dots,g_m({\mathbf{x}}_s))\big)\in \mathcal{M}_{2t}(\varphi(\mathcal{X})), 
            \\
            \widetilde{\mathit{y}} &=& \psi_k(\pi_k(\widetilde{\mathit{y}}^\prime))= \sum_{s=1}^Nw_s \mathbf{v}_k({\mathbf{x}}_s) \in \mathcal{M}_k(\mathcal{X}).
         \end{eqnarray*}
     \end{enumerate}
