     \textbf{Evaluating $\|\mathit{y} -\overline{\mathit{y}}\|$:} 
     We apply Lemma~\ref{lem: bounded of M_k(B_R x Delta)} to $\mathbf{d}_k(\mathcal{T}(\mathbb{B}_R \times \Delta_K^m)_{2t})$ under the degree condition $t \geq 4(\max\{n,m\}+1)k+2$ for a product of two simple sets  to obtain that 
     \begin{multline}\label{eq: y to y bar}
       \|\mathit{y} - \overline{\mathit{y}}\| =
       \|\psi_k(\pi_k(\widehat{\mathit{y}}^\varphi)) - \psi_k(\pi_k(\overline{\mathit{y}}^\prime))\|
       \leq \|\pi_k(\widehat{\mathit{y}}^{\varphi})- \pi_k(\overline{\mathit{y}}^\prime)\| 
       \\ 
       \;\leq\; \mathbf{d}_k(\mathcal{T}(\mathbb{B}_R \times \Delta_K^m)_{2t}) \;\leq\; \dfrac{\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)}{(t-2)^2} =: \varepsilon.
     \end{multline}

     \textbf{Evaluating $\|\overline{\mathit{y}}-\widetilde{\mathit{y}}\|$:} We use the same argument as in the proof of Theorem~\ref{thm: error on variety} to derive the following inequality:
     \begin{displaymath}
          \sum_{s=1}^N w_s \max\left\{ |h_i(\overline{\mathbf{x}}_s)|:\ i \in [p]\right\} \leq \varepsilon^{1/2} \sum_{i=1}^p \|h_i\|_1.
     \end{displaymath}

     For $j \in [m]$, we consider $q_j(\mathbf{z}) = (g_j(\mathbf{x})-u_j)^2$. Then we have
     \begin{align*}
         \ell_{\widehat{\mathit{y}}^{\varphi}}(q_j) = \ell_{\mathit{y}}((g_j(\mathbf{x})-g_j(\mathbf{x}))^2) =0,\quad \mbox{and} \quad \|q_j\|_1\leq (1+\|g_j\|_1)^2.
     \end{align*}
     Note that ${\rm deg}(q_j) \leq 4d \leq k.$ Next, using the Cauchy–Schwarz inequality and the fact that 
     $\overline{\mathbf{u}}_s=(\overline{u}_{s1},\ldots,\overline{u}_{sm}) \geq 0\; \forall\; s\in [N]$, we have 
     \begin{align*}
     &\sum_{s=1}^Nw_sq_j(\overline{\mathbf{z}}_s) = 
     \sum_{s=1}^Nw_sq_j(\overline{\mathbf{z}}_s)-\ell_{\widehat{\mathit{y}}^{\varphi}}(q_j) 
     = \left\langle {\bf q}_j,\overline{\mathit{y}}^\prime - \widehat{\mathit{y}}^{\varphi} \right\rangle
     \leq \varepsilon  \|q_j\|_1 \quad \mbox{(by \eqref{eq: y to y bar})}
     \\
     \Rightarrow & 
     \sum_{s=1}^N w_s(g_j(\overline{\mathbf{x}}_s)-\overline{u}_{sj})^2 \leq \varepsilon \|q_j\|_1 
     \quad \Rightarrow \quad 
     \sum_{s=1}^Nw_s \max \{0, -g_j(\overline{\mathbf{x}}_s)\}^2 \leq \varepsilon \|q_j\|_1\\
     \Rightarrow & \sum_{s=1}^N w_s\max \{0, -g_j(\overline{\mathbf{x}}_s)\} \leq \left( \sum_{s=1}^Nw_s\right)^{1/2}\left( \sum_{s=1}^Nw_s \max \{0, -g_j(\overline{\mathbf{x}}_s)\}^2\right)^{1/2} \leq \varepsilon^{1/2}(1+\|g_j\|_1)\\
     \Rightarrow & \sum_{s=1}^Nw_s \max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}\leq \varepsilon^{1/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right).
     \end{align*}

     Furthermore, the Łojasiewicz inequality~\eqref{Lojaciewicz inequality} implies that
    \begin{displaymath}
        \|\mathbf{x}_s -\overline{\mathbf{x}}_s\| = \mathbf{d}(\overline{\mathbf{x}}_s,\mathcal{X}) \leq c\max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}^{\textit{\L}}.
    \end{displaymath}

    Let  $L(R,k)>0$ be the Lipschitz number of $\mathbf{v}_k(\mathbf{x})$ on the ball $\mathbb{B}_R$. Then it directly leads to the inequality:
    \begin{displaymath}
        \|\mathbf{v}_k(\mathbf{x}_s) - \mathbf{v}_k(\overline{\mathbf{x}}_s)\| \leq L(R,k) \|\mathbf{x}_s -\overline{\mathbf{x}}_s\|  \leq cL(R,k) \max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}^{\textit{\L}}.
    \end{displaymath}
    Hence, we obtain that 
    \begin{eqnarray*}
        \|\overline{\mathit{y}}-\widetilde{\mathit{y}} \| &=&
        \left\|\sum_{s=1}^N w_s\mathbf{v}_k(\overline{\mathbf{x}}_s) -
        \sum_{s=1}^N w_s\mathbf{v}_k(\mathbf{x}_s)\right\|
        \\  
        &\leq& cL(R,k)\sum_{s=1}^N w_s\max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}^{\textit{\L}}.
    \end{eqnarray*} 
    Recall that $\textit{\L} \leq 1$, applying Jensen's inequality gives us the following inequality:
        \begin{align}\label{eq: y bar to y tidle}
            &\sum_{s=1}^N w_s\max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}^{\textit{\L}}\nonumber\\
            \leq &\ \left(\sum_{s=1}^N w_s\max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}\right)^{\textit{\L}}\nonumber\\
            \Rightarrow &\ \sum_{s=1}^N w_s\max \left\{-g_j(\overline{\mathbf{x}}_s),|h_i(\overline{\mathbf{x}}_s)|:\ i\in [p],\ j\in [m]\right\}^{\textit{\L}} \leq\varepsilon^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}\nonumber\\
            \Rightarrow&\ \|\overline{\mathit{y}}-\widetilde{\mathit{y}} \| 
            \leq cL(R,k)\varepsilon^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}.
        \end{align}
        We substitute \eqref{eq: y to y bar} and \eqref{eq: y bar to y tidle} back to \eqref{eq: inequality of distance with compactness} to obtain that
        \begin{align*}
            &\mathbf{d}(\mathit{y},\mathcal{M}_k(\mathcal{X})) \leq \varepsilon+cL(R,k)
            \varepsilon^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}} \quad 
            \forall \mathit{y} \in \mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r})
            \\
            \Rightarrow& \ \mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) \leq \varepsilon+cL(R,k)
            \varepsilon^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}.
        \end{align*}
        By the definition $t$, we have $t \geq \frac{r-2d}{2d}$. Hence, we obtain that
