            \mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) \leq \Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)\dfrac{(2d)^2}{(r-4d)^2}
            \\
            +\frac{cL(R,k)(2d)^{\textit{\L}}}{(r-4d)^{\textit{\L}}}
            [\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)]^{\textit{\L}/2}
        \left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}.
        \end{multline*}
        This completes the proof.

