     \end{multline*}
     In conclusion, it is shown that the error for Schmüdgen-type truncated pseudo-moment sequences on a compact basic semi-algebraic $\mathcal{X}$ is $\mathrm{O}(1/r^{\textit{\L}})$, where $\textit{\L}$ is the Łojasiewicz exponent depending on the polynomial inequalities defining $\mathcal{X}$.

\begin{multline*}
          f_{\min}-\mathrm{lb}(f,\mathcal{R}(\mathcal{X}))_r \leq \Biggl[\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)\dfrac{(2d)^2}{(r-4d)^2}\\+\frac{cL(R,k)(2d)^{\textit{\L}}}{(r-4d)^{\textit{\L}}}
            [\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)]^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}\Biggr]\cdot \|f\|_1.
