To do so, we define the violating function $g$, which indicates how much the inequalities $g_j(\mathbf{x}) \leq 0$ are violated at the point $\mathbf{x}\in\mathbb{R}^n$, i.e, 
 \begin{displaymath}
     g(\mathbf{x}) = \max\{0,\ g_i(\mathbf{x}):\ i \in [m]\} \quad \Rightarrow \quad\mathcal{X} = \{\mathbf{x} \in \mathbb{R}^n:\ g(\mathbf{x}) = 0\}.

In particular, the Fréchet subdifferential of $g$ at $\mathbf{x}$, denoted by $\partial^Fg(\mathbf{x})$ is the set of vectors $\mathbf{w}$ satisfying the following condition:
\begin{displaymath}
    \mathbf{w} \in \partial^Fg(\mathbf{x}) \ \Leftrightarrow \ \liminf_{\mathbf{y} \to \mathbf{x}}\dfrac{g(\mathbf{y}) - g(\mathbf{x})-\langle \mathbf{w},\mathbf{y}-\mathbf{x} \rangle}{\|\mathbf{y} -\mathbf{x}\|} \geq 0.

\end{displaymath}
The limiting subdifferential of $g$ at $\mathbf{x}$, denoted by $\partial^Lg(\mathbf{x})$, consists of vectors $\mathbf{w} \in \partial^Fg(\mathbf{x})$ such that
\begin{displaymath}
    \exists \mathbf{x}_n \to \mathbf{x},\ \exists \mathbf{w}_n \to \mathbf{w}, \quad \mbox{satisfying} \quad g(\mathbf{x}_n) \to g(\mathbf{x})
     \;\;\mbox{and}\;\; 
    \mathbf{w}_n \in \partial^Fg(\mathbf{x}_n).

\begin{equation}\label{def LP}
    \forall \mathbf{x} \in \mathbb{R}^n, \quad g(\mathbf{x}) -\inf g \leq \dfrac{1}{2\mu}\|\mathbf{w}\|^2\quad \forall\; \mathbf{w} \in \partial^Lg(\mathbf{x}).
\end{equation}

\label{lemma: PL }
    Let $q: \mathbb{R}^n \to \mathbb{R}$ be a continuous function whose set of global minimizers $\mathrm{argmin}\, q$ is nonempty. Assume that $q$ is globally $\mu-$PŁ with constant $\mu >0$. Then the Łojasiewicz exponent $\textit{\L} = \frac{1}{2}$ and the Łojasiewicz constant is $\sqrt{\frac{2}{\mu}}$ for the distance to the set $\mathrm{argmin}\, q$, i.e,
    \begin{displaymath}
        \mathbf{d}(\mathbf{x}, \mathrm{argmin}\ q) \leq \sqrt{\dfrac{2}{\mu}} \big(q(\mathbf{x}) -\inf_{\mathbb{R}^n} q\big)^{1/2}, \quad \forall \mathbf{x} \in \mathbb{R}^n.
    \end{displaymath}

\begin{assume}\label{assumption: convexisty}
    We assume that $\mathcal{X}$ is defined by the polynomial inequalities $g_i(\mathbf{x}) \leq 0$ for all $i\in[m]$, where $g_i$'s are locally strongly convex function with the constant $\mu_i >0$, i.e., there exists a compact convex set $\Omega$ such that $\mathcal{X} \subset \Omega$ and for any $\mathbf{x}, \mathbf{y} \in \Omega$ and $i \in [m]$, the following inequality holds
    \begin{displaymath}
        g_i(\mathbf{y}) \geq g_i(\mathbf{x}) + \left \langle \nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \dfrac{\mu_i}{2}\|\mathbf{y}-\mathbf{x}\|^2.

\label{assumption: convexisty}
    We assume that $\mathcal{X}$ is defined by the polynomial inequalities $g_i(\mathbf{x}) \leq 0$ for all $i\in[m]$, where $g_i$'s are locally strongly convex function with the constant $\mu_i >0$, i.e., there exists a compact convex set $\Omega$ such that $\mathcal{X} \subset \Omega$ and for any $\mathbf{x}, \mathbf{y} \in \Omega$ and $i \in [m]$, the following inequality holds
    \begin{displaymath}
        g_i(\mathbf{y}) \geq g_i(\mathbf{x}) + \left \langle \nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \dfrac{\mu_i}{2}\|\mathbf{y}-\mathbf{x}\|^2.
    \end{displaymath}
    In addition, we set $\mu = \min\{ \mu_i,\ i \in [m]\} >0$. Then the inequality 
    \begin{displaymath}
        g_i(\mathbf{y}) \geq g_i(\mathbf{x}) + \left \langle \nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2
    \end{displaymath}
    holds for all $\mathbf{x}, \mathbf{y} \in \Omega$ and $i \in [m]$. In this case, we call the set $\mathcal{X}$ a $\mu$-strongly convex semi-algebraic set.

\label{lemma: (LSC) to (LPL)}
    Let $\mathcal{X}$ be a non-empty, $\mu-$strongly convex semi-algebraic set contained in a compact convex set $\Omega$, i.e., $\mathcal{X} \subset \Omega$,
    and for any $\mathbf{x}, \mathbf{y} \in \Omega$ and $i \in [m]$, the following inequality holds for some positive parameter $\mu$:
    \begin{displaymath}
        g_i(\mathbf{y}) \geq g_i(\mathbf{x}) + \left \langle \nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2.
    \end{displaymath}
    Then the function $g$ is $\mu-$P$\textit{\L}$ on $\Omega$, i.e., for any $\mathbf{x} \in \Omega$ and $\mathbf{w} \in \partial^Lg(\mathbf{x})$, we have that 
    \begin{displaymath}
        g(\mathbf{x}) -\inf_{\Omega} g \leq \dfrac{1}{2\mu}\|\mathbf{w}\|^2.
    \end{displaymath}

Since the functions $0, g_1, \dots, g_m$ are convex, $g$ is convex. Thus, the Fréchet subdifferential and the limiting subdifferential of $g$ are both equal to the classical subdifferential for a convex function~\cite[Proposition 8.12]{variational_analysis}, i.e.,
\begin{displaymath}
    \partial^Fg(\mathbf{x}) = \partial^Lg(\mathbf{x}) = \partial g(\mathbf{x}),
\end{displaymath}
where $\partial g(\mathbf{x})$ denotes the subdifferential of $g$. We next consider our desired inequality. For any $\mathbf{x} \in \mbox{argmin}(g)$, i.e., $g(\mathbf{x})= \inf_{\Omega}g$, it is obvious that the following inequality
\begin{equation*}
    g(\mathbf{x}) - \inf_{\Omega}g = 0 \leq\frac{1}{2\mu}\|\mathbf{w}\|^2, \quad \forall \ \mathbf{w} \in \partial^Lg(\mathbf{x})
\end{equation*} 
holds true. For $\mathbf{x} \in \Omega \backslash \mbox{argmin}(g)$, $g(\mathbf{x}) > 0$. Thus, the set $A(\mathbf{x})$ of active indices at $\mathbf{x}$, defined as
\begin{displaymath}
     A(\mathbf{x}) = \{i \in [m]:\ g(\mathbf{x}) = g_i(\mathbf{x})\} \neq \emptyset.
\end{displaymath}
 Additionally, we can combine it with \cite[Example 5.4.5]{Dimitri-convex} to obtain the subdifferential of the maximum of differentiable functions as
 \begin{displaymath}
     \partial^Fg(\mathbf{x}) = \partial^Lg(\mathbf{x}) = \partial g(\mathbf{x}) = \mathrm{conv}\{\nabla g_i(\mathbf{x})\; :\; i \in A(\mathbf{x})\}.
 \end{displaymath}
 For any $\mathbf{w} \in \partial g(\mathbf{x})$, we set $\mathbf{w} = \sum_{i \in  A(\mathbf{x})} w_i\nabla g_i(\mathbf{x})$ where $0 \leq w_i \leq 1$ for all $i \in A(\mathbf{x})$ and $\sum_{i \in A(\mathbf{x})}w_i =1$. Then we have that 
\begin{align*}
    &g_i(\mathbf{y}) \geq g_i(\mathbf{x}) + \left \langle \nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2\\
    \Rightarrow & \  \sum_{i \in A(\mathbf{x})}w_ig_i(\mathbf{y}) \geq \sum_{i \in A(\mathbf{x})}w_ig_i(\mathbf{x}) + \left \langle  \sum_{i \in A(\mathbf{x})}w_i\nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \sum_{i \in A(\mathbf{x})}w_i\dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2\\
    \Rightarrow & \  g(\mathbf{y}) \geq g(\mathbf{x}) + \left\langle \mathbf{w},\mathbf{y}-\mathbf{x} \right\rangle + \dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2, \ \forall \mathbf{x}, \mathbf{y} \in \Omega,\ \mathbf{w} \in \partial g(\mathbf{x}).
\end{align*}
Since $\mathcal{X}$ is a non-empty set contained in $\Omega$, there exists a point $\mathbf{x}^* \in \mbox{argmin}(g) \subset \Omega$ . Applying the last inequality and the Cauchy–Schwarz inequality, we  obtain that 
\begin{displaymath}
    \inf_{\Omega}\ g = g(\mathbf{x}^*) \geq g(\mathbf{x}) + \left\langle \mathbf{w},\mathbf{x}^*-\mathbf{x} \right\rangle + \dfrac{\mu}{2}\|\mathbf{x}^*-\mathbf{x}\|^2 \geq g(\mathbf{x}) - \dfrac{1}{2\mu}\|\mathbf{w}\|^2.
\end{displaymath}
Hence, we obtain that $g(\mathbf{x}) - \inf_\Omega g \leq \frac{1}{2\mu}\|\mathbf{w}\|^2 \ \forall \mathbf{w} \in \partial g(\mathbf{x})= \partial^L g(\mathbf{x}),\ \forall \mathbf{x} \in \Omega$, which is the local version of the P\L\ condition \eqref{def LP} on $\Omega$.

\begin{equation*}
        g(\mathbf{x}) - \inf_{\Omega}g = 0 \leq\frac{1}{2\mu}\|\mathbf{w}\|^2, \quad \forall \ \mathbf{w} \in \partial^Lg(\mathbf{x})
    \end{equation*}

\begin{align*}
        &g_i(\mathbf{y}) \geq g_i(\mathbf{x}) + \left \langle \nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2\\
        \Rightarrow & \  \sum_{i \in A(\mathbf{x})}w_ig_i(\mathbf{y}) \geq \sum_{i \in A(\mathbf{x})}w_ig_i(\mathbf{x}) + \left \langle  \sum_{i \in A(\mathbf{x})}w_i\nabla g_i(\mathbf{x}),\mathbf{y} -\mathbf{x} \right \rangle + \sum_{i \in A(\mathbf{x})}w_i\dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2\\
        \Rightarrow & \  g(\mathbf{y}) \geq g(\mathbf{x}) + \left\langle \mathbf{w},\mathbf{y}-\mathbf{x} \right\rangle + \dfrac{\mu}{2}\|\mathbf{y}-\mathbf{x}\|^2, \ \forall \mathbf{x}, \mathbf{y} \in \Omega,\ \mathbf{w} \in \partial g(\mathbf{x}).
    \end{align*}

\label{lemma: (LPL) to (LLI)}
     Let $\mathcal{X}$ satisfies Assumption \ref{assumption: convexisty}. 
     Then the following Łojasiewicz inequality holds:
     \begin{displaymath}
         \mathbf{d}(\mathbf{x},\mathcal{X}) \leq \sqrt{\dfrac{2}{\mu}}
         g(\mathbf{x})^{1/2}\quad \forall\; \mathbf{x} \in \Omega.
     \end{displaymath}

According to Lemma~\ref{lemma: (LSC) to (LPL)}, the P\L\ condition holds on $\Omega$, i.e.,
\begin{displaymath}
    g(\mathbf{x}) - \inf_\Omega g \leq \frac{1}{2\mu}\|\mathbf{w}\|^2 \quad \forall \mathbf{w} \in \partial g(\mathbf{x}),\quad \forall \mathbf{x} \in \Omega.
\end{displaymath}
Now consider the function
\begin{displaymath}
     f(\mathbf{x}) = 
       \begin{cases} 
           g(\mathbf{x}) & \text{if } \mathbf{x} \in \Omega, \\
           +\infty & \text{if } \mathbf{x} \notin \Omega,
       \end{cases}
\end{displaymath}
which is a convex lower semi-continuous function on $\mathbb{R}^n$ with $\textrm{dom}\ f = \Omega$ and satisfies the P\L\ condition on $\Omega$. Observe that $\inf_{\mathbb{R}^n} f = \inf_{\Omega} g =0$, and $\textrm{argmin}\ f = \mathcal{X}$.
For any $\widehat{\mathbf{x}} \in \Omega$, we construct a sequence $(\mathbf{x}_k)_{k \in \mathbb{N}}$ as follows: $\mathbf{x}_0 =\widehat{\mathbf{x}}$, and 
\begin{displaymath}
    \mathbf{x}_{k+1} \in \underset{\mathbf{x} \in \mathbb{R}^n}{\textrm{argmin }} f(\mathbf{x}) + \dfrac{1}{2}\|\mathbf{x}-\mathbf{x}_k\|^2, \quad S_{k+1} = \{\mathbf{x} \in \mathbb{R}^n:\ f(\mathbf{x}) \leq f(\mathbf{x}_{k+1})\}.
   \end{displaymath}
   Then the level sets $S_k \subset \Omega \ \forall k \in \mathbb{N}$, and $f(\mathbf{x}_{k+1}) + \dfrac{1}{2}\|\mathbf{x}_{k+1} - \mathbf{x}_k\|^2 \leq f(\mathbf{x}) + \dfrac{1}{2}\|\mathbf{x} - \mathbf{x}_k\|^2\ \forall \mathbf{x} \in \mathbb{R}^n$. Hence, we obtain that 
   \begin{displaymath}
       \|\mathbf{x}_{k+1}-\mathbf{x}_{k}\|^2 \leq \|\mathbf{x}-\mathbf{x}_{k}\|^2 \;\; \forall\; \mathbf{x} \in S_{k+1}\quad \Rightarrow \quad \|\mathbf{x}_{k+1}-\mathbf{x}_{k}\| = \mathbf{d}(\mathbf{x}_k,S_{k+1}).
   \end{displaymath}

   We next consider the function $\varphi(t) = \sqrt{\dfrac{2}{\mu}}t^{1/2}$. Then $\varphi'(t) =\dfrac{1}{\sqrt{2\mu}}t^{-1/2}$ and $\varphi^{-1}(t) = \dfrac{\mu}{2}t^2$. Since $\inf_{\mathbb{R}^n} f =0$, the P\L\ condition can be written equivalently as
   \begin{displaymath}
       f(\mathbf{x}) -\inf_{\mathbb{R}^n} f \leq \dfrac{1}{2\mu}\|\mathbf{w}\|^2 \quad \Leftrightarrow \quad 1 \leq \varphi'(f(\mathbf{x})) \|\mathbf{w}\| \quad \forall \mathbf{x} \in \Omega,\ \forall\; \mathbf{w} \in \partial f(\mathbf{x}).
   \end{displaymath}
   We use the chain rule to obtain that 
   \begin{displaymath}
       \partial(\varphi \circ f)(\mathbf{x}) \subset \varphi'(f(\mathbf{x}))\partial f(\mathbf{x}) \quad \Rightarrow \quad 1 \leq \|\mathbf{v}\| \;\; \forall \mathbf{v} \in \partial(\varphi \circ f)(\mathbf{x}),\quad \forall\; \mathbf{x}\in \Omega.
   \end{displaymath}
   The above  result can be combined with the condition of \cite[Proposition 4.6]{curves-of-descent} to show that the limiting slope of $f$ at $\mathbf{x}$ (see e.g., \cite{curves-of-descent,Characterizations-of-LP}), denoted by $\left|\overline{\nabla }f(\mathbf{x})\right|$, satisfies that
   \begin{displaymath}
       \left|\overline{\nabla }f(\mathbf{x})\right| = \mathbf{d}(0, \partial f(\mathbf{x})) = \inf \left\{\|\mathbf{v}\|,\ \mathbf{v} \in \partial f(\mathbf{x}) \right\} \geq 1 \ \forall\; \mathbf{x} \in \Omega.
   \end{displaymath}

    We note that a convex function is subdifferential regular at every point of its effective domain (see e.g., \cite[Proposition 8.21]{variational_analysis}). Then the slope and the limiting slope coincides. Thus, the assumption on the K\L-inequality and 
    sub-level set mapping in \cite[Corollary 4]{Characterizations-of-LP} is satisfied, which when combines with the definition of $S_k = \{ \mathbf{x} \in \mathbb{R}^n:\ 0 \leq f(\mathbf{x}) \leq f(\mathbf{x}_k)\} \subset \Omega$ leads to the following inequality:
   \begin{displaymath}
       \|\mathbf{x}_{k+1}-\mathbf{x}_{k}\|= \mathbf{d}(\mathbf{x}_k,S_{k+1}) \leq \varphi(f(\mathbf{x}_k)) -\varphi(f(\mathbf{x}_{k+1})). 
   \end{displaymath}

   We note that $\mathbf{x}_0 =\widehat{\mathbf{x}}$. The above inequality gives
   \begin{equation} \label{eq-PL}
       \|\mathbf{x}_{k+1}-\widehat{\mathbf{x}}\| \leq \sum_{i=0}^k\|\mathbf{x}_{i+1}-\mathbf{x}_i\| \leq \sum_{i=0}^k 
       \varphi(f(\mathbf{x}_{i}))-\varphi(f(\mathbf{x}_{i+1})) \leq \varphi(f(\widehat{\mathbf{x}})).
   \end{equation}
   Furthermore, since $(\mathbf{x}_k)_{k \in \mathbb{N}} \subset \Omega$,  the compactness of $\Omega$ ensures the existence of a limit point $\overline{\mathbf{x}}$ of $\{\mathbf{x}_k: k \in \mathbb{N}\}$. Without loss of generality, we can assume that $\lim_{k \to \infty} \mathbf{x}_k = \overline{\mathbf{x}}$. The first-order optimality condition and the local P\L\ condition for $f$ imply that 
   \begin{align*}
       &\mathbf{x}_k - \mathbf{x}_{k+1} \in \partial f(\mathbf{x}_{k+1}) \ \Rightarrow \ f(\mathbf{x}_{k+1}) \leq \dfrac{1}{2\mu}\|\mathbf{x}_k-\mathbf{x}_{k+1}\|^2 \\ \Rightarrow &\ f(\overline{\mathbf{x}}) = \lim_{k \to \infty}f(\mathbf{x}_k) \leq \frac{1}{2\mu}\lim_{k \to \infty}\|\mathbf{x}_k-\mathbf{x}_{k+1}\|^2 =0.
   \end{align*}
   Hence, $\overline{\mathbf{x}} \in \textrm{argmin\;}f$. Moreover, \eqref{eq-PL} implies that 
   $$
    \|\widehat{\mathbf{x}}-\overline{\mathbf{x}}\| \leq \varphi(f(\widehat{\mathbf{x}})). 
   $$
   Now the increasing property of $\varphi^{-1}$ implies the following inequality:
   \begin{displaymath}
