\label{thm: error on sphere}
    Let $k,l$ and $r$ be positive integers such that $k=2l$ and $2r\geq k$. Then the Hausdorff distance $\mathbf{d}_k(\mathcal{Q}(S_R^{n-1})_{2r}) =\mathbf{d}_k(\mathcal{T}(S_R^{n-1})_{2r})$ admits the following upper bound:
    \begin{equation}\label{error on sphere}
        \mathbf{d}_k(\mathcal{T}(S_R^{n-1})_{2r}) \leq   
        \left(1+ \frac{\sqrt{n}L(R,k)}{R} \right)\frac{2\gamma(R,n,k)\Gamma(\mathbb{B}_R,k)}{r^2}.
    \end{equation}

\begin{equation}\label{error on sphere}
        \mathbf{d}_k(\mathcal{T}(S_R^{n-1})_{2r}) \leq   
        \left(1+ \frac{\sqrt{n}L(R,k)}{R} \right)\frac{2\gamma(R,n,k)\Gamma(\mathbb{B}_R,k)}{r^2}.
    \end{equation}

We first proceed as in the proof of Theorem~\ref{thm: error on variety}. Let $\mathit{y} \in \mathcal{M}_k(\mathcal{T}(S_R^{n-1})_{2r})$. Then $\mathit{y} \in \mathcal{M}_k(\mathcal{T}(\mathbb{B}_R)_{2r})$, and there exists the projection $\overline{\mathit{y}}$ of $\mathit{y}$ onto $\mathcal{M}_k(\mathbb{B}_R)$ such that 
\begin{displaymath}
    \|\mathit{y} -\overline{\mathit{y}}\| \;\leq\; \frac{2\gamma(R,n,k) \Gamma(\mathbb{B}_R,k)}{r^2}=: \varepsilon.
\end{displaymath}
Moreover, there exists $N \leq  s(n,k) $ points $\{\overline{\mathbf{x}}_s:\; s\in[N]\}$ in $\mathbb{B}_R$ and positive weight $\{w_s:\; s\in [N]\}$ with $\sum_{s=1}^Nw_s =1$ satisfying that 
\begin{displaymath}
    \overline{\mathit{y}}= \sum_{s=1}^Nw_s\mathbf{v}_k(\overline{\mathbf{x}}_s).
\end{displaymath}
Applying the Cauchy–Schwarz inequality to $\left|\ell_{\mathit{y}}(R^2-\|\mathbf{x}\|^2)-\ell_{\overline{\mathit{y}}}(R^2-\|\mathbf{x}\|^2)\right|$, we obtain the following:
\begin{align*}
    &\left|\ell_{\mathit{y}}(R^2-\|\mathbf{x}\|^2)-\ell_{\overline{\mathit{y}}}(R^2-\|\mathbf{x}\|^2)\right|  
    \leq  \sum_{i=1}^n |y_{2e_i} - \overline{y}_{2e_i}|
    \leq \sqrt{n}\|y-\overline{y}\|      
    \\
    \Rightarrow\;& \left|\ell_{\overline{\mathit{y}}}(R^2-\|\mathbf{x}\|^2) \right| 
    \leq \sqrt{n}\varepsilon \quad \text{(since $\ell_{\mathit{y}}(R^2 - \|\mathbf{x}\|^2) = 0$)}\\
    \Rightarrow\;& \sum_{s=1}^Nw_s(R^2-\|\overline{\mathbf{x}}_s\|^2) \leq \sqrt{n}\varepsilon.
\end{align*}
Define $\widetilde{\mathbf{x}}_s = R\,{\overline{\mathbf{x}}_s}/{\|\overline{\mathbf{x}}_s\|} \in S_R^{n-1}$ to be the projection of $\overline{\mathbf{x}}_s$ onto $S_R^{n-1}$.
Then we can bound the distance between $\overline{\mathbf{x}}_s$ and 
$\widetilde{\mathbf{x}}_s$ as follows:
\begin{displaymath}
    \|\widetilde{\mathbf{x}}_s-\overline{\mathbf{x}}_s\| = \left\|\overline{\mathbf{x}}_s\left(\frac{R}{\|\overline{\mathbf{x}}_s\|}-1 \right)\right\|= R-\|\overline{\mathbf{x}}_s\| 
    \leq \frac{(R+\|\overline{\mathbf{x}}_s\|)(R-\|\overline{\mathbf{x}}_s\|)}{R}= \frac{R^2-\|\overline{\mathbf{x}}_s\|^2}{R}.
\end{displaymath}
We set $\widetilde{\mathit{y}}= \sum_{s=1}^Nw_s\mathbf{v}_k(\widetilde{\mathbf{x}}_s)$. Since $\widetilde{\mathbf{x}}_s \in S_R^{n-1}\; \forall s \in [N]$, $\widetilde{\mathit{y}} \in \mathcal{M}_k(S_R^{n-1})$. Moreover, let $L(R,k)$ be the Lipschitz number of $\mathbf{v}_k(\mathbf{x})$ on the ball $\mathbb{B}_R$. Then we can perform the following evaluation on the distance between $\overline{\mathit{y}}$ and $\widetilde{\mathit{y}}$ as follows:
\begin{align*}
    &\|\overline{\mathit{y}}-\widetilde{\mathit{y}}\| \leq \sum_{s=1}^Nw_s\|\mathbf{v}_k(\overline{\mathbf{x}}_s)-\mathbf{v}_k(\widetilde{\mathbf{x}}_s)\| \leq \sum_{s=1}^Nw_sL(R,k)\|\overline{\mathbf{x}}_s-\widetilde{\mathbf{x}}_s\|\\
    \leq\; & \sum_{s=1}^Nw_sL(R,k)\frac{R^2-\|\overline{\mathbf{x}}_s\|^2}{R} 
    = \frac{L(R,k)}{R}\sum_{s=1}^Nw_s(R^2-\|\overline{\mathbf{x}}_s\|^2) \leq \frac{\sqrt{n}L(R,k)}{R}\varepsilon.
\end{align*}
Hence, we can bound the distance from $\mathit{y}$ to $\mathcal{M}_k(S_R^{n-1})$ as 
\begin{displaymath}
    \mathbf{d}_k(\mathcal{T}(S_R^{n-1})_{2r}) \leq \|\mathit{y} -\widetilde{\mathit{y}}\| \leq \|\mathit{y} - \overline{\mathit{y}}\| + \| \overline{\mathit{y}}-\widetilde{\mathit{y}}\| \leq \varepsilon\left(1+ \frac{\sqrt{n}L(R,k)}{R} \right). 
\end{displaymath}
In conclusion, we obtain the desired bound.
This completes the proof.

\begin{align*}
        &\|\overline{\mathit{y}}-\widetilde{\mathit{y}}\| \leq \sum_{s=1}^Nw_s\|\mathbf{v}_k(\overline{\mathbf{x}}_s)-\mathbf{v}_k(\widetilde{\mathbf{x}}_s)\| \leq \sum_{s=1}^Nw_sL(R,k)\|\overline{\mathbf{x}}_s-\widetilde{\mathbf{x}}_s\|\\
