\text{\cite[Theorem 2.10 and Theorem 2.14]{Baldi_2025}}\label{thm: CQC}
    Consider the domain 
    \begin{displaymath}
        \mathcal{X} = \{\mathbf{x} \in \mathbb{R}^n:\; g_i(\mathbf{x}) \geq 0,\; i\in [m] \}. 
    \end{displaymath}
    For $\mathbf{x} \in \mathcal{X}$, let $I(\mathbf{x})$ be the set of active indices (the index $i$ is said to be active if $g_i(x) = 0$). We say that the Constraint Qualification Condition (CQC) holds at $\mathbf{x}$ if $\{ \nabla g_i(x):\; i \in I(\mathbf{x})\} $ are linearly independent. 

    We say that $\mathcal{X}$ satisfy the CQC if the CQC holds at every point of $\mathcal{X}$. In this case, the Łojasiewicz exponent is equal to $1$.

\label{thm: error on image}
        Let $\mathcal{X}$ be a product of simple sets defined by 
        \begin{displaymath}
        \mathcal{X} := \{ \mathbf{x} \in \mathbb{R}^n:\ g_j(\mathbf{x}) \geq 0\ \forall j \in [m]\}.
    \end{displaymath}
     Let $k= 2l$ be a positive even integer, $A$ be an invertible matrix in $\mathbb{R}^{n\times n}$. Then the image of $\mathcal{X}$ via $A$ remains a basic semi-algebraic set defined by
    \begin{displaymath}
        A(\mathcal{X}) = \{\mathbf{x} \in \mathbb{R}^n:\  g_j(A^{-1}\mathbf{x}) \geq 0\ \forall j \in [m]\}.
    \end{displaymath}
    We have the following upper bound on the error of truncated pseudo-moment sequences:
    \begin{displaymath}
        \mathbf{d}_k(\mathcal{T}(A(\mathcal{X})))_r \leq \Gamma(A(\mathcal{X}),k)\dfrac{\gamma(R,n,k)}{r^2},
    \end{displaymath}
    where $\Gamma(A(\mathcal{X})),k)$ is a polynomial in the dimension $n$, the norm of  $A$ and $k$. The result also holds true for $\mathcal{Q}(A(\mathcal{X}))_{2r}$ and $\mathcal{R}(A(\mathcal{X}))_{2r}$.

        Denote the rows of $A$ by $a_i^\top$ for $i \in [n]$, and we define an isomorphism $\overline{A}$ on the $\mathbb{R}[\mathbf{x}]-$algebra induced by 
        $A$ as follows:
    \begin{align*}
        \overline{A}: \mathbb{R}[\mathbf{x}] \to \mathbb{R}[\mathbf{x}],  

        \quad 
        \overline{A}\mathbf{x}^\alpha = (A\mathbf{x})^\alpha = \prod_{i=1}^n \langle a_i,\mathbf{x} \rangle^{\alpha_i}.
    \end{align*}
    Since $A$ is invertible,  for all $\alpha \in \mathbb{N}^n$, the degree of the polynomial $(A\mathbf{x})^{\alpha}=\prod_{i=1}^n\langle a_i, \mathbf{x} \rangle^{\alpha_i}$ remains to be $|\alpha|$. We denote the restriction of $\overline{A}$ on $\mathbb{R}[\mathbf{x}]_{2r}$ by $\overline{A}_{2r}$. Fix $\mathbf{v}_{2r}(\mathbf{x}) = (\mathbf{x}^{\alpha})_{\alpha \in \mathbb{N}^n_{2r}}$ to be a basis of the linear space $\mathbb{R}[\mathbf{x}]_{2r}$. Then for any $p(\mathbf{x}) \in \mathbb{R}[\mathbf{x}]_{2r}$, there exists a unique vector $\mathbf{p} \in \mathbb{R}^{s(n,2r)}$ such that 
    \begin{displaymath}
        p(\mathbf{x})= \sum_{\alpha \in \mathbb{N}^n_{2r}}p_{\alpha}\mathbf{x}^{\alpha} = \langle \mathbf{p},\mathbf{v}_{2r}(\mathbf{x})\rangle, \quad \mathbf{p}:= (p_{\alpha})_{\alpha \in \mathbb{N}^n_{2r}}.
    \end{displaymath}
    The mapping $\varphi_{2r}: p(\mathbf{x}) \mapsto \mathbf{p}$ is an isomorphism between $\mathbb{R}[\mathbf{x}]_{2r}$ and $\mathbb{R}^{s(n,2r)}$. We next define the linear transformation $\mathcal{A}_{2r}:\mathbb{R}^{s(n,2r)}\to \mathbb{R}^{s(n,2r)}$ as follows:
    \begin{equation}\label{define transformation}
        \mathcal{A}_{2r}= \varphi_{2r}\circ \overline{A}_{2r}\circ \varphi_{2r}^{-1}.
    \end{equation}
     Let 
     $\{e_{\alpha}\}_{\alpha \in \mathbb{N}^n_{2r}}$ be the standard basis of $\mathbb{R}^{s(n,2r)}$.
    In particular, $\mathcal{A}_{2r}(e_\alpha) = \varphi_{2r}((A\mathbf{x})^\alpha)$ for all $\alpha\in \mathbb{N}^n_{2r}$.

     We claim that $\mathcal{A}_{2r}(\mathcal{M}(\mathcal{T}(\mathcal{X})_{2r}))= \mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r})\ \forall r \in \mathbb{N}$. Indeed, let $\mathit{y} \in \mathcal{M}(\mathcal{T}(\mathcal{X})_{2r})$, i.e., $\mathit{y}$ satisfies the following conditions
     \begin{displaymath}
         \mathit{y}_0 = 1, \quad \mathbf{M}_r(\mathit{y}) \succeq 0,\quad \mathbf{M}_{r-\degg{g_J}}(g_J\mathit{y}) \succeq 0 \quad \forall J \subset [m],\; 
         \degg{g_J} \leq r.
     \end{displaymath}
    Set $\overline{\mathit{y}}= \mathcal{A}_{2r}(\mathit{y})$. To prove that $\overline{\mathit{y}} \in \mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r})$, we check the following constraints on $\overline{\mathit{y}}$ 
    \begin{equation}\label{condition 1}
       \overline{\mathit{y}}_0 = 1, \quad  \mathbf{M}_r(\overline{\mathit{y}}) \succeq 0,\quad \mathbf{M}_{r-\degg{g_J}}((g_J\circ A^{-1})\overline{\mathit{y}}) \succeq 0 \quad \forall J \subset [m],\; \degg{g_J} \leq r.
     \end{equation}
     Let $[\overline{A}_{2r}]$ be the representation matrix of $\overline{A}_{2r}$ on $\mathbb{R}[\mathbf{x}]_{2r}$ with respect to the basis $\{\mathbf{x}^{\alpha}\}_{\alpha \in \mathbb{N}^n_{2r}}$.
     Then for any $\alpha \in \mathbb{N}^n_{2r}$, we have that 
     \begin{align*}
         \mathcal{A}_{2r} (e_{\alpha}) &\;= \varphi_{2r} \circ \overline{A}_{2r} \circ \varphi_{2r}^{-1}(e_{\alpha})
         \;=\; \varphi_{2r} \circ \overline{A}_{2r}(\mathbf{x}^{\alpha})
        \;=\; \varphi_{2r} ( (A\mathbf{x})^\alpha)
         \;=\; [\overline{A}_{2r}] e_{\alpha}
     \end{align*}
