     So $[\overline{A}_{2r}]$ is also the representation matrix of $\mathcal{A}_{2r}$ on $\mathbb{R}^{s(n,2r)}$ with respect to the standard basis.
     Moreover, for any $\alpha,\, \beta \in \mathbb{N}^n_r$, the $(\alpha,\beta)$-entry of $[\overline{A}_{2r}]$ is $e_{\alpha}^{\top}[\overline{A}_{2r}]e_{\beta} = e_\beta^\top [\overline{A}_{2r}]^\top e_\alpha $, which is the coefficients of $\mathbf{x}^{\beta}$ in the polynomial $(A\mathbf{x})^{\alpha}$.
     Therefore, we have 
     \begin{displaymath}
         \overline{\mathit{y}}_0 =\langle e_0, \overline{\mathit{y}} \rangle= \langle  e_0, [\overline{A}_{2r}] y \rangle
         = \sum_{\alpha} y_\alpha 
         \langle e_0, \varphi_{2r}((A\mathbf{x})^\alpha) \rangle
         = y_0 =1.
     \end{displaymath}
     For the rest of the conditions in  \eqref{condition 1}, we adopt the convention that $g_{\emptyset} =1$ and $d_{\emptyset} =0$. 
     Then $\mathbf{M}_r(\overline{\mathit{y}}) = \mathbf{M}_{r-d_{\emptyset}}( (g_{\emptyset}\circ A^{-1})\overline{\mathit{y}})$. 
     Hence, it suffices to prove that for any $J \subset [m]$ and 
     $\degg{g_J} \leq r$, $\mathbf{M}_{r-\degg{g_J}}((g_J\circ A^{-1})\overline{\mathit{y}}) \succeq 0$.
     Let $t=r-\degg{g_J}$.  We will prove that $\mathbf{M}_{t}((g_J\circ A^{-1})\overline{\mathit{y}})= [\overline{A}_{t}]^{\top}\mathbf{M}_{t}(g_J\mathit{y})[\overline{A}_{t}]$, and the semidefiniteness of $\mathbf{M}_{t}((g_J\circ A^{-1})\overline{\mathit{y}})$ will then follow from that of $\mathbf{M}_{t}(g_J\mathit{y})$. Here $\overline{A}_{t}$ is the restriction of $\overline{A}$ on $\mathbb{R}[\mathbf{x}]_{t}$, whose representation matrix with respect to the basis $\{\mathbf{x}^{\alpha}\}_{\alpha \in \mathbb{N}^n_{t}}$ is $[\overline{A}_{t}]$. 
     Let $d_J = \degg{g_J}.$ For any $\alpha,\beta \in \mathbb{N}^n_t$, 
     we observe that 
     \begin{align*}
         &\mathbf{M}_{t}((g_J\circ A^{-1})\overline{\mathit{y}})(\alpha,\beta)= \sum_{\gamma \in \mathbb{N}^n_{2d_J}}(g_J \circ A^{-1})_{\gamma}\overline{\mathit{y}}_{\alpha + \beta+\gamma}
