         =\;&\sum_{\gamma \in \mathbb{N}^n_{2d_J}}(g_J \circ A^{-1})_{\gamma}\left\langle e_{\alpha+\beta+\gamma},[\overline{A}_{2r}]\mathit{y} \right\rangle
         \\
         =\;& \sum_{\tau \in \mathbb{N}^n_{2r}}\sum_{\gamma \in \mathbb{N}^n_{2d_J}}(g_J \circ A^{-1})_{\gamma} [\overline{A}_{2r}]_{\alpha+\beta+\gamma, \tau}\cdot\mathit{y}_{\tau}.
     \end{align*}
     We consider the coefficient of $\mathit{y}_{\tau}$ in the last sum
     \begin{align*}
         &\sum_{\gamma \in \mathbb{N}^n_{2d_J}}(g_J \circ A^{-1})_{\gamma} [\overline{A}_{2r}]_{\alpha+\beta+\gamma, \tau}
