     We next consider the $(\alpha,\beta)-$entry of $[\overline{A}_{t}]^{\top}\mathbf{M}_{t}(g_J\mathit{y})[\overline{A}_{t}]$ given as follows:
     \begin{align*}
         &[\overline{A}_{t}]^{\top}\mathbf{M}_{t}(g_J\mathit{y})[\overline{A}_{t}](\alpha,\beta)= ([\overline{A}_{t}]e_{\alpha})^{\top}\mathbf{M}_{t}(g_J\mathit{y})([\overline{A}_{t}]e_{\beta})
         \;=\;\sum_{\sigma, \theta \in \mathbb{N}^n_t}[\overline{A}_t]_{\sigma,\alpha}[\overline{A}_t]_{\theta,\beta}\sum_{\gamma \in \mathbb{N}^n_{2d_J}}(g_J)_{\gamma}\mathit{y}_{\sigma+\theta+\gamma}.
     \end{align*}
     Then for any $\tau \in \mathbb{N}^n_{2r}$, the coefficient of $\mathit{y}_{\tau}$ in the last sum is 
     \begin{align*}
         \sum_{\substack{\sigma, \theta \in \mathbb{N}^n_r, \gamma \in \mathbb{N}^n_{2d_J}\\ \sigma+\theta +\gamma= \tau}}[\overline{A}_t]_{\sigma,\alpha}[\overline{A}_t]_{\theta,\beta}(g_J)_{\gamma},
     \end{align*}
     which is the coefficient of $\mathbf{x}^{\tau}$ in the product $g_J(\mathbf{x})(A\mathbf{x})^{\alpha}(A\mathbf{x})^{\beta}=(A\mathbf{x})^{\alpha+\beta}\cdot g_J(\mathbf{x}) $. Hence, the $(\alpha,\beta)-$entries of $\mathbf{M}_{t}((g_J\circ A^{-1})\overline{\mathit{y}})$ and $ [\overline{A}_{t}]^{\top}\mathbf{M}_{r-\degg{g_J}}(g_J\mathit{y})[\overline{A}_{t}]$ coincide. Consequently, we have 
     \begin{displaymath}
         \mathcal{A}_{2r}(\mathcal{M}(\mathcal{T}(\mathcal{X})_{2r}))\subset \mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r}).
     \end{displaymath}

     Since $A$ is invertible, we use the same argument to prove that 
     \begin{displaymath}
         \mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r})=\mathcal{A}^{-1}_{2r}(\mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r}))\subset \mathcal{M}(\mathcal{T}(\mathcal{X})_{2r}),
     \end{displaymath}
     where $\mathcal{A}^{-1}_{2r} =\varphi_{2r}\circ 
     (\overline{A}_{2r})^{-1}\circ \varphi_{2r}^{-1}$, and $(\overline{A}_{2r})^{-1}$ is the inverse of $\overline{A}_{2r}$.
     Applying $\mathcal{A}_{2r}$ to the above inclusion, we get 
     \begin{displaymath}
         \mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r})\subset \mathcal{A}_{2r}
         (\mathcal{M}(\mathcal{T}(\mathcal{X})_{2r})).
     \end{displaymath}
     Thus we have proved that $ \mathcal{A}_{2r}
         (\mathcal{M}(\mathcal{T}(\mathcal{X})_{2r}))=\mathcal{M}(\mathcal{T}(A(\mathcal{X}))_{2r}).$

     Now consider any $2r-$truncated moment sequence $y\in \mathcal{M}_{2r}(\mathcal{X})$.
    By Tchakaloff's theorem, 
     there exist at most $N = s(n,2r)$ points $\{\mathbf{x}_1,\ldots,\mathbf{x}_N\}$ in $\mathcal{X}$ and positive scalars 
     $\{w_1,\ldots,w_N\}$ satisfying $\sum_{i=1}^Nw_i=1$ such that 
     \begin{displaymath}
         \mathit{y} = \sum_{i=1}^Nw_i\mathbf{v}_{2r}(\mathbf{x}_i).
     \end{displaymath}
     Then  $\mathcal{A}_{2r}(\mathit{y}) =  \sum_{i=1}^Nw_i \varphi_{2r}(\mathbf{v}_{2r}(A\mathbf{x}_i))$, and $A\mathbf{x}_i \in A(\mathcal{X}) \; \forall i \in [N]$.
     Hence, we also have $\mathcal{A}_{2r}(\mathcal{M}_{2r}(\mathcal{X})) = \mathcal{M}_{2r}(A(\mathcal{X}))$. Combining this with the result in the last paragraph, we obtain that 
     \begin{displaymath}
         \mathbf{d}_{k}(\mathcal{T}(A(\mathcal{X}))_{2r}) \leq \|\pi_k \circ \mathcal{A}_{2r}\|_2 \,\mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r})\quad \forall k \leq 2r.
     \end{displaymath}
     In conclusion, the error estimation for the $k-$truncated 
pseudo-moment problem on $A(\mathcal{X})$ is conveyed from that on $\mathcal{X}$.
The same holds true for the convergence rate of the moment-SOS hierarchy
on $A(\mathcal{X})$.

