Let $p \in \mathbb{R}[\mathbf{x}]_k$ be a polynomial of degree $k$ and we assume that $\|p\|_{\mathcal{X}} =1 $. Recall that $\mu = \otimes_{i=1}^m\mu_i$, where $\mu_i$ is the measure corresponding to the simple set $\mathcal{X}_i$ as in Table~\ref{tab:measure}. We know from the proof of Lemma~\ref{lem: equivalent kernel} that for $j_1,\dots,j_m$ such that $j_1 + \dots + j_m \leq k$,
\begin{equation*}
    p_{j_1,\dots,j_m}(\mathbf{x}) = \int_{\mathcal{X}}\left[\prod_{i=1}^m C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)}, \overline{\mathbf{x}}^{(i)})\right]p(\overline{\mathbf{x}})d\mu(\overline{\mathbf{x}}) \quad \forall\; \mathbf{x} \in \mathcal{X}.
\end{equation*}
We use the Cauchy–Schwarz inequality and the fact that $\|p\|_{\mathcal{X}} = 1$ to obtain that 
\begin{align*}
    |p_{j_1,\dots,j_m}(\mathbf{x})|^2 &= \left|\int_{\mathcal{X}}\left[\prod_{i=1}^m C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)}, \overline{\mathbf{x}}^{(i)})\right]p(\overline{\mathbf{x}})d\mu(\overline{\mathbf{x}}) \right|^2\\
    &\leq \int_{\mathcal{X}}\left[\prod_{i=1}^m C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)}, \overline{\mathbf{x}}^{(i)})\right]^2d\mu(\overline{\mathbf{x}}) \cdot \int_{\mathcal{X}}p(\overline{\mathbf{x}})^2d\mu(\overline{\mathbf{x}})\\
    &\leq \prod_{i=1}^m \int_{\mathcal{X}_i}C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)}, \overline{\mathbf{x}}^{(i)})^2d\mu_i(\overline{\mathbf{x}}^{(i)}).
\end{align*}
Using the property of the CD kernel, we have:
\begin{equation*}
    \int_{\mathcal{X}_i}C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)}, \overline{\mathbf{x}}^{(i)})^2d\mu_i(\overline{\mathbf{x}}^{(i)}) = C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)},\mathbf{x}^{(i)}).
\end{equation*}
Then it follows that 
\begin{align*}
    \Lambda(\mathcal{X},k)^2 &= \max_{p \in \mathbb{R}[\mathbf{x}]_k}\max_{j_1 + \dots + j_m \leq k} \frac{\|p_{j_1,\dots,j_m}\|_{\mathcal{X}}^2}{\|p\|_{\mathcal{X}}^2} \leq \max_{j_1 + \dots + j_m \leq k} \max_{\mathbf{x} \in \mathcal{X}}\ \prod_{i=1}^mC^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)},\mathbf{x}^{(i)})\\
    &\leq \max_{j_1 + \dots + j_m \leq k} \prod_{i=1}^m \max_{\mathbf{x}^{(i)} \in \mathcal{X}_i} C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)},\mathbf{x}^{(i)})\\
    &\leq \prod_{i=1}^m \tau(\mathcal{X}_i,k), \quad \mbox{where} \quad \tau(\mathcal{X}_i,k):=\max_{0 \leq j_i \leq k}\max_{\mathbf{x}^{(i)} \in \mathcal{X}_i} C^{(j_i)}[\mathcal{X}_i,\mu_i](\mathbf{x}^{(i)},\mathbf{x}^{(i)}).
 \end{align*}
 We recall from the works \cite{slot2111sum} and \cite{laurent2023effective} that $\tau(\mathcal{X}_i,k)$ depends polynomially on $n_i$ for fixed $k$ and polynomially on $k$ for fixed $n_i$. This leads to our required result. We refer to \cite{slot2111sum} and \cite{laurent2023effective} for the explicit bound on each $\tau(\mathcal{X}_i,k)$ that can be used  to derive an explicit bound on $\Lambda(\mathcal{X},k)$ in terms of $k$ and $n_i$'s.

